def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def is_multiply_prime(a):
    for i in range(2, a):
        if a % i == 0 and is_prime(i):
            for j in range(i, a):
                if a % j == 0 and is_prime(j):
                    for k in range(j, a):
                        if a % k == 0 and is_prime(k) and i * j * k == a:
                            return True
    return False
